-- Additive local candidate mechanics. No educational/scientific release or
-- actual scientific admission is activated by this migration.
alter table private.part_four_release add column scientific_manifest_hash text
 check(scientific_manifest_hash is null or scientific_manifest_hash ~ '^[a-f0-9]{64}$');

create function private.part_four_release_tuple(r private.part_four_release) returns jsonb
language sql immutable set search_path='' as $$
 select jsonb_build_object('releaseId',r.release_id,'releaseHash',r.release_hash,'knowledgeVersion',r.knowledge_version,'knowledgeHash',r.knowledge_hash)
  ||case when r.scientific_manifest_hash is null then '{}'::jsonb else jsonb_build_object('scientificManifestHash',r.scientific_manifest_hash) end;
$$;
create table private.part_four_historical_releases (
 release_hash text primary key check(release_hash ~ '^[a-f0-9]{64}$'),
 tuple jsonb not null, permitted boolean not null default false,
 check(tuple->>'releaseHash'=release_hash)
);
alter table private.part_four_historical_releases enable row level security;
revoke all on private.part_four_historical_releases from public,anon,authenticated;
grant all on private.part_four_historical_releases to service_role;

create function private.part_four_release_history_guard() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if old.permitted and private.part_four_release_tuple(old) is distinct from private.part_four_release_tuple(new)
  and not old.release_hash=any(old.withdrawn_hashes) and not old.knowledge_hash=any(old.withdrawn_hashes) then
  insert into private.part_four_historical_releases(release_hash,tuple,permitted) values(old.release_hash,private.part_four_release_tuple(old),true)
  on conflict(release_hash) do nothing;
 end if;
 return new;
end $$;
create trigger part_four_release_history_guard before update on private.part_four_release for each row execute function private.part_four_release_history_guard();
create function private.part_four_saved_release_allowed(t jsonb) returns boolean
language sql security definer set search_path='' as $$
 select t is not null and not exists(select 1 from private.part_four_source_withdrawals w where w.dependency_id in(t->>'releaseHash',t->>'knowledgeHash',t->>'scientificManifestHash'))
  and exists(select 1 from private.part_four_release r where r.id and not (t->>'releaseHash'=any(r.withdrawn_hashes)) and not(t->>'knowledgeHash'=any(r.withdrawn_hashes))
   and (r.permitted and t=private.part_four_release_tuple(r) or exists(select 1 from private.part_four_historical_releases h where h.permitted and h.tuple=t)));
$$;

-- Independent source/scientific authority. Empty by default. Lifecycle fixtures
-- use original synthetic propositions only; real records require actual review.
create table private.part_four_scientific_authority (
 manifest_hash text not null check(manifest_hash ~ '^[a-f0-9]{64}$'),
 claim_hash text not null check(claim_hash ~ '^[a-f0-9]{64}$'), claim_id text not null,
 reviewer_id text not null, qualification_ref text not null,
 source_ids text[] not null, source_metadata jsonb not null check(jsonb_typeof(source_metadata)='array'), grant_id text not null, grant_version text not null,
 allowed_state text not null check(allowed_state in('supported','reference')),
 reason text not null, action text, qualifications jsonb not null check(jsonb_typeof(qualifications)='array'),
 valid_until timestamptz not null, process boolean not null default false,
 store boolean not null default false, display boolean not null default false,
 export boolean not null default false, revoked boolean not null default false,
 primary key(manifest_hash,claim_hash)
);
alter table private.part_four_scientific_authority enable row level security;
revoke all on private.part_four_scientific_authority from public,anon,authenticated;
grant all on private.part_four_scientific_authority to service_role;
create trigger part_four_scientific_fence before insert or update or delete on private.part_four_scientific_authority for each statement execute function private.part_four_truth_lifecycle_fence();
create trigger part_four_scientific_projection after update or delete on private.part_four_scientific_authority for each statement execute function private.part_four_truth_projection();
create trigger part_four_historical_fence before update or delete on private.part_four_historical_releases for each statement execute function private.part_four_truth_lifecycle_fence();
create trigger part_four_historical_projection after update or delete on private.part_four_historical_releases for each statement execute function private.part_four_truth_projection();

create function private.part_four_science_field_allowed(f jsonb,p_now timestamptz,p_purpose text default 'display') returns boolean
language plpgsql security definer set search_path='' as $$
declare a private.part_four_scientific_authority; v jsonb:=f->'value'; g jsonb; source jsonb;
begin
 if f->>'kind'<>'scientific_claim' or f->>'state'<>'retained' or v='null'::jsonb then return false; end if;
 select * into a from private.part_four_scientific_authority where manifest_hash=v->>'manifestHash' and claim_hash=v->'assessment'->>'claimHash' for share;
 if not found or a.revoked or a.valid_until<=p_now or not(a.process and a.store) or p_purpose in('save','display') and not a.display or p_purpose='export' and not a.export
  or a.claim_id is distinct from v->'assessment'->>'claimId' or a.allowed_state is distinct from v->'assessment'->>'state'
  or a.reviewer_id is distinct from v->'assessment'->>'admissionId' or a.reason is distinct from v->'assessment'->>'reason'
  or a.action is distinct from v->'assessment'->>'action' or a.qualifications is distinct from v->'assessment'->'reasons'
  or (v->'assessment'->>'validUntil')::timestamptz<=p_now or (v->'assessment'->>'validUntil')::timestamptz>a.valid_until then return false; end if;
 if jsonb_array_length(f->'grants')<>cardinality(a.source_ids) or (select count(distinct value->>'sourceId') from jsonb_array_elements(f->'grants'))<>cardinality(a.source_ids) or (select count(distinct value->>'id') from jsonb_array_elements(v->'sources'))<>cardinality(a.source_ids) then return false; end if;
 if exists(select 1 from private.part_four_source_withdrawals w where w.dependency_id in(a.manifest_hash,a.claim_hash,a.claim_id,a.reviewer_id,a.qualification_ref,a.grant_id,a.grant_version) or w.dependency_id=any(a.source_ids)) then return false; end if;
 if (select coalesce(array_agg(x order by x),'{}'::text[]) from jsonb_array_elements_text(f->'sourceIds') x)
  is distinct from (select coalesce(array_agg(x order by x),'{}'::text[]) from unnest(a.source_ids) x) then return false; end if;
 for g in select value from jsonb_array_elements(f->'grants') loop
  if g->>'field'<>'science' or not(g->>'sourceId'=any(a.source_ids)) or g->>'policyId'<>a.grant_id or g->>'policyVersion'<>a.grant_version
   or g->'operations'->>'process'<>'true' or g->'operations'->>'store'<>'true' or p_purpose in('save','display') and g->'operations'->>'display'<>'true'
   or g->'operations'->>'export' is distinct from a.export::text or g->>'revoked'<>'false' or (g->>'validUntil')::timestamptz<=p_now or (g->>'validUntil')::timestamptz>a.valid_until then return false; end if;
 end loop;
 for source in select value from jsonb_array_elements(v->'sources') loop
  if not(source->>'id'=any(a.source_ids)) or (source->>'validUntil')::timestamptz<=p_now or (source->>'validUntil')::timestamptz>a.valid_until
   or not exists(select 1 from jsonb_array_elements(a.source_metadata) q where q.value=source-'validUntil') then return false; end if;
 end loop;
 return jsonb_array_length(v->'sources')=cardinality(a.source_ids);
exception when others then return false;
end $$;

create function private.part_four_science_current(p jsonb) returns boolean
language plpgsql security definer set search_path='' as $$
declare row jsonb; f jsonb; source jsonb; s jsonb:=p->'partFour'->'scientificDecision';
begin
 if s is null then return true; end if;
 if s->>'manifestHash' is distinct from p->'binding'->'releases'->'partFour'->>'scientificManifestHash' then return false; end if;
 for row in select value from jsonb_array_elements(s->'assessments') where value->'assessment'->>'state' in('supported','reference') loop
  select value into f from jsonb_array_elements(p->'partFour'->'retainedEvidence'->'fields') where value->>'kind'='scientific_claim' and value->'value'->'assessment'=row->'assessment' and value->'value'->'goal'=row->'goal';
  if f is null or not private.part_four_science_field_allowed(f,clock_timestamp()) then return false; end if;
 end loop;
 for source in select value from jsonb_array_elements(s->'sourceRefs') loop
  if not exists(select 1 from jsonb_array_elements(p->'partFour'->'retainedEvidence'->'fields') q,
   lateral jsonb_array_elements(q.value->'value'->'sources') refs where q.value->>'kind'='scientific_claim' and q.value->>'state'='retained' and refs.value=source) then return false; end if;
 end loop;
 return true;
exception when others then return false;
end $$;

-- Upgrade the exact current registry comparison without broadening any P1/P2/P3
-- owner/context/source checks. Fail migration if its inspected seam changed.
do $patch$
declare d text; needle text; replacement text; signature text;
begin
 foreach signature in array array['private.part_three_binding_current(uuid,jsonb,uuid,boolean)','private.part_four_packet_sources_current(jsonb)'] loop
  d:=pg_get_functiondef(signature::regprocedure);
  needle:=case when signature like '%part_three_binding%' then 'jsonb_build_object(''releaseId'',p4.release_id,''releaseHash'',p4.release_hash,''knowledgeVersion'',p4.knowledge_version,''knowledgeHash'',p4.knowledge_hash)' else 'jsonb_build_object(''releaseId'',rel.release_id,''releaseHash'',rel.release_hash,''knowledgeVersion'',rel.knowledge_version,''knowledgeHash'',rel.knowledge_hash)' end;
  replacement:=case when signature like '%part_three_binding%' then 'private.part_four_release_tuple(p4)' else 'private.part_four_release_tuple(rel)' end;
  if position(needle in d)=0 then raise exception 'PART_FOUR_REGISTRY_SEAM_CHANGED'; end if;
  d:=replace(d,needle,replacement);
  if signature like '%part_three_binding%' then
   needle:='if not found or not p4.permitted or p4.release_hash=any(p4.withdrawn_hashes)'||chr(10)||'   or b->''releases''->''partFour'' is distinct from private.part_four_release_tuple(p4)';
   if position(needle in d)=0 then raise exception 'PART_FOUR_HISTORICAL_BINDING_SEAM_CHANGED'; end if;
   d:=replace(d,needle,'if not found or (case when not p_context_required and p_pinned is not null then not private.part_four_saved_release_allowed(b->''releases''->''partFour'') else not p4.permitted or p4.release_hash=any(p4.withdrawn_hashes) or b->''releases''->''partFour'' is distinct from private.part_four_release_tuple(p4) end)');
  end if;
  if signature like '%sources_current%' then d:=replace(d,' return true;'||chr(10)||'exception when others then return false;',' return private.part_four_science_current(p_packet);'||chr(10)||'exception when others then return false;'); end if;
  execute d;
 end loop;
end $patch$;

-- Reuse the original packet whitelist/projection; add only scientific fields.
alter function private.part_four_retained_packet(jsonb,text,timestamptz,text[]) rename to part_four_retained_packet_pre_science;
create function private.part_four_retained_packet(p_packet jsonb,p_purpose text,p_now timestamptz,p_withdrawn text[] default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare p jsonb; s jsonb:=p_packet->'partFour'->'scientificDecision'; row jsonb; a jsonb; f jsonb; rows jsonb:='[]'; sources jsonb:='[]'; insights jsonb:='[]'; insight jsonb; findings jsonb:='[]'; finding jsonb; removed text[]:='{}'; unavailable text[]:='{}'; primary_lost boolean:=false; changed boolean:=false; lost_goals text[]:='{}'; goal text; gap_id text;
begin
 p:=private.part_four_retained_packet_pre_science(p_packet,p_purpose,p_now,p_withdrawn);
 if s is null or p->'partFour' is null then return p; end if;
 for row in select value from jsonb_array_elements(s->'assessments') loop
  a:=row->'assessment';
  if a->>'state' in('supported','reference') then
   select value into f from jsonb_array_elements(p->'partFour'->'retainedEvidence'->'fields') where value->>'kind'='scientific_claim' and value->'value'->'assessment'=a and value->'value'->'goal'=row->'goal';
   if f is null or not private.part_four_science_field_allowed(f,p_now,'display') then
    changed:=true;unavailable:=array_append(unavailable,'scientific:'||(a->>'claimId')||':'||coalesce(row->>'goal','routine'));
    if a->>'state'='supported' and row->>'goal' is not null then lost_goals:=array_append(lost_goals,row->>'goal'); end if;
    a:=a||jsonb_build_object('state','unavailable','reason',null,'action',null,'reasons',jsonb_build_array('Saved scientific source evidence is unavailable.'),'sourceIds','[]'::jsonb,'factIds','[]'::jsonb,'contextRevisionIds','[]'::jsonb,'admissionId',null,'validUntil',null,'missingFields','[]'::jsonb);
   else
    sources:=sources||f->'value'->'sources';
   end if;
  end if;
  rows:=rows||jsonb_build_array(jsonb_set(row,'{assessment}',a));
 end loop;
 s:=s||jsonb_build_object('assessments',rows,'sourceRefs',(select coalesce(jsonb_agg(v order by v->>'id',v->>'reviewedAt',v->>'validUntil'),'[]') from (select distinct value v from jsonb_array_elements(sources)) q));
 select coalesce(array_agg(distinct g),'{}') into lost_goals from unnest(lost_goals) g where g not in('maintain','simplify') and not exists(select 1 from jsonb_array_elements(rows) q where q.value->>'goal'=g and q.value->'assessment'->>'state'='supported');
 s:=jsonb_set(s,'{unresolvedGoals}',(select coalesce(jsonb_agg(distinct g),'[]') from (select value g from jsonb_array_elements(coalesce(s->'unresolvedGoals','[]')) union select to_jsonb(g) from unnest(lost_goals) g) q));
 p:=jsonb_set(p,'{partFour,scientificDecision}',s,true);
 if not changed then return p; end if;
 foreach goal in array lost_goals loop
  gap_id:='gap:goal_evidence:goal:'||goal;
  if not exists(select 1 from jsonb_array_elements(p->'materialGaps') q where q.value->>'id'=gap_id) then p:=jsonb_set(p,'{materialGaps}',coalesce(p->'materialGaps','[]')||jsonb_build_array(jsonb_build_object('id',gap_id,'affectedPropositionIds',jsonb_build_array('goal:'||goal),'state','unavailable','reason','goal_evidence','recoverableBy','reviewer'))); end if;
  if p->'summary' is not null then p:=jsonb_set(p,'{summary,materialGapIds}',(select coalesce(jsonb_agg(distinct g),'[]') from (select value g from jsonb_array_elements(coalesce(p->'summary'->'materialGapIds','[]')) union select to_jsonb(gap_id)) q)); end if;
 end loop;
 for finding in select value from jsonb_array_elements(p->'findings') loop
  if finding->>'id'=any(unavailable) then
   removed:=array_append(removed,finding->>'id');
   primary_lost:=primary_lost or p->'summary'->>'primaryFindingId'=finding->>'id';
  else findings:=findings||jsonb_build_array(finding); end if;
 end loop;
 p:=jsonb_set(p,'{findings}',findings);
 if p->>'selectedTradeoffId'=any(removed) then p:=jsonb_set(p,'{selectedTradeoffId}','null'); end if;
 for insight in select value from jsonb_array_elements(p->'partFour'->'insights') loop
  if insight->>'id' like 'science:%' and exists(select 1 from jsonb_array_elements(rows) q where q.value->'assessment'->>'state'='unavailable' and insight->>'id'='science:'||(q.value->'assessment'->>'claimId')||':'||coalesce(nullif(q.value->>'goal',''),'routine')) then
   insight:=insight||jsonb_build_object('state','unknown','explanation','Saved scientific source evidence is unavailable.','action',null,'sourceIds','[]'::jsonb,'factIds','[]'::jsonb,'contextRevisionIds','[]'::jsonb);
  end if;
  insights:=insights||jsonb_build_array(insight);
 end loop;
 p:=jsonb_set(p,'{partFour,insights}',insights);
 p:=jsonb_set(p,'{partFour,decisionState}','"pending"');
 p:=jsonb_set(p,'{partFour,action}','"Review the unavailable saved evidence before relying on this check."');
 if primary_lost or cardinality(lost_goals)>0 and p->'summary'->>'judgment'='worth_considering' then
  p:=jsonb_set(p,'{summary}',p->'summary'||jsonb_build_object('judgment','not_enough_info','displayVariant','default','primaryFindingId',null,'affirmativePremiseIds','[]'::jsonb,'overridingFindingIds','[]'::jsonb));
 elsif p->'summary' is not null then
  p:=jsonb_set(p,'{summary,affirmativePremiseIds}',(select coalesce(jsonb_agg(value),'[]') from jsonb_array_elements(p->'summary'->'affirmativePremiseIds') where not(value#>>'{}'=any(removed))));
  p:=jsonb_set(p,'{summary,overridingFindingIds}',(select coalesce(jsonb_agg(value),'[]') from jsonb_array_elements(p->'summary'->'overridingFindingIds') where not(value#>>'{}'=any(removed))));
 end if;
 return p;
exception when others then return null;
end $$;

create or replace function private.part_four_purge_retained_sources() returns void
language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare withdrawn text[];
begin
 withdrawn:=private.part_four_withdrawn_dependencies();perform pg_advisory_xact_lock(40206);
 update public.part_three_results set payload=null,state='pending',lease_token=null,expires_at=clock_timestamp()
 where payload->'partFour' is not null and (not private.part_four_packet_basis_current(owner_id,payload,true) or not private.part_four_packet_sources_current(payload));
 update public.part_three_saved_assessments set packet=private.part_four_retained_packet(private.part_four_saved_routine_projection(owner_id,packet),'retain',clock_timestamp(),withdrawn)
 where packet->'partFour' is not null;
 update public.part_three_saved_assessments set packet=null,binding_hash=null,result_revision=null
 where packet->'partFour' is not null and not private.part_four_saved_release_allowed(packet->'binding'->'releases'->'partFour');
end $$;

-- Display/export projection must remove all duplicated scientific copy too,
-- not merely null the nested retained-evidence transport field.
do $patch$
declare d text; needle text; replacement text;
begin
 d:=pg_get_functiondef('public.part_three_worker(uuid,text,jsonb)'::regprocedure);
 needle:='result:=jsonb_set(result,''{assessmentWhenSaved,partFour,retainedEvidence}'',private.part_four_reproject_retained_evidence(result->''assessmentWhenSaved''->''partFour''->''retainedEvidence'',''display'',clock_timestamp(),withdrawn));';
 replacement:='result:=jsonb_set(result,''{assessmentWhenSaved}'',private.part_four_retained_packet(result->''assessmentWhenSaved'',''display'',clock_timestamp(),withdrawn));';
 if position(needle in d)=0 then raise exception 'PART_FOUR_HISTORICAL_DISPLAY_SEAM_CHANGED'; end if;
 execute replace(d,needle,replacement);
end $patch$;

revoke all on function private.part_four_retained_packet_pre_science(jsonb,text,timestamptz,text[]),private.part_four_retained_packet(jsonb,text,timestamptz,text[]) from public,anon,authenticated;
grant execute on function private.part_four_retained_packet(jsonb,text,timestamptz,text[]) to service_role;

revoke all on function private.part_four_release_tuple(private.part_four_release),private.part_four_release_history_guard(),private.part_four_saved_release_allowed(jsonb),private.part_four_science_field_allowed(jsonb,timestamptz,text),private.part_four_science_current(jsonb) from public,anon,authenticated;
grant execute on function private.part_four_release_tuple(private.part_four_release),private.part_four_saved_release_allowed(jsonb),private.part_four_science_field_allowed(jsonb,timestamptz,text),private.part_four_science_current(jsonb) to service_role;

-- Generated from the exact updated closed-object TypeScript whitelist.
create or replace function private.part_four_retention_schema() returns jsonb
language sql immutable set search_path='' as $schemafn$
