$schemafn$;

do $patch$
declare d text;
begin
 d:=pg_get_functiondef('private.part_four_retained_evidence_valid(jsonb)'::regprocedure);
 if position('if f->>''kind'' like ''brief_%'' and g->>''field''<>''brief'' then return false; end if;' in d)=0 then raise exception 'PART_FOUR_SCIENCE_GRANT_SEAM_CHANGED'; end if;
 d:=replace(d,
  'if f->>''kind'' like ''brief_%'' and g->>''field''<>''brief'' then return false; end if;',
  'if f->>''kind'' like ''brief_%'' and g->>''field''<>''brief'' then return false; end if; if f->>''kind''=''scientific_claim'' and g->>''field''<>''science'' then return false; end if;');
 execute d;
 d:=pg_get_functiondef('private.part_four_reproject_retained_evidence(jsonb,text,timestamptz,text[])'::regprocedure);
 if position('if exists(select 1 from jsonb_array_elements_text(f->''withdrawalIds'') d where d.value=any(all_withdrawn)) then' in d)=0 then raise exception 'PART_FOUR_SCIENCE_RETENTION_SEAM_CHANGED'; end if;
 d:=replace(d,
  'if exists(select 1 from jsonb_array_elements_text(f->''withdrawalIds'') d where d.value=any(all_withdrawn)) then',
  'if f->>''kind''=''scientific_claim'' and not private.part_four_science_field_allowed(f,p_now,p_purpose) then state:=''tombstoned'';reason:=''source_tombstone''; elsif exists(select 1 from jsonb_array_elements_text(f->''withdrawalIds'') d where d.value=any(all_withdrawn)) then');
 execute d;
end $patch$;
